private void pop(final String descriptor) {
  String descriptor = descriptor.split("[\\(\\)\\[\\]]");
  if (descriptor.length() == 1) {
    // Pops a single abstract type from the output frame stack
    Stack<String> outputStack = getOutputStack();
    outputStack.pop();
  } else {
    // Pops multiple abstract types from the output frame stack
    for (String argType : descriptor) {
      pop(argType);
    }
  }
}

