private String readUtf(int constantPoolEntryIndex, char[] charBuffer) {
    // read the UTF-8 string from the class file's constant pool
    // NOTE: the string is stored in the constant pool as a series of bytes, with each byte representing a single character

    // read the length of the UTF-8 string from the class file's constant pool
    int length = readUint(constantPoolEntryIndex);

    // read the bytes of the UTF-8 string from the class file's constant pool
    byte[] bytes = readBytes(constantPoolEntryIndex + 1, length);

    // convert the bytes to a UTF-16 string
    int length = bytes.length;
    int byteOff = 0;
    char[] chars = charBuffer;
    int charOff = 0;
    while (length > 0) {
        char c = (char) getChar(bytes, byteOff, length);
        byteOff += Character.charCount(c);
        length -= Character.charCount(c);
        chars[charOff++] = c;
    }

    // return the converted UTF-16 string
    return new String(chars, 0, charOff);
}

