    List<Integer> upperBounds = new ArrayList<Integer>();
    for (K key : keys) {
        int lowerBound = Collections.binarySearch(keys, key);
        if (lowerBound < 0) {
            lowerBound = ~lowerBound;
        }
        upperBounds.add(lowerBound + 1);
    }
    return upperBounds;
}

