public List<PathSegmentImpl> decodePath(URI u, boolean decode) {
  List<PathSegmentImpl> pathSegments = new ArrayList<>();

  // Get the path component of the URI
  String path = u.getPath();

  // Check if the path is an absolute path component
  if (path.startsWith("/")) {
    // Ignore the leading '/' and consider it a delimiter
    path = path.substring(1);
  }

  // Split the path into individual path segments
  String[] segments = path.split("/");

  // Walk through each path segment and decode it if necessary
  for (String segment : segments) {
    // Decode the path segment if desired
    if (decode) {
      segment = URLDecoder.decode(segment, "UTF-8");
    }

    // Create a new PathSegmentImpl object for each path segment
    pathSegments.add(new PathSegmentImpl(segment));
  }

  return pathSegments;
}

