private Class findClass(final String className) throws ClassNotFoundException {
    Class<?> cls = null;
    try {
        cls = Class.forName(className);
    } catch (ClassNotFoundException e) {
        // Ignore this exception, we'll handle it below
    }

    if (cls == null) {
        // Try again with the initial class loader
        cls = Class.forName(className, true, Thread.currentThread().getContextClassLoader());
    }

    if (cls == null) {
        // Try again with the default class loader
        cls = Class.forName(className, true, ClassLoader.getSystemClassLoader());
    }

    if (cls == null) {
        // We haven't found the class, throw an exception
        throw new ClassNotFoundException("Class " + className + " not found");
    }

    return cls;
}

