  String homeDir = System.getProperty("user.home");

  // Create the "lf5" directory if it doesn't exist
  String configDir = homeDir + File.separator + "lf5";
  File f = new File(configDir);
  if (!f.exists()) {
    File[] dirs = new File[configDir.split(File.separator).length];
    for (int i = 0; i < dirs.length; i++) {
      dirs[i] = new File(configDir.split(File.separator)[i]);
      if (!dirs[i].exists()) {
        dirs[i].mkdir();
      }
    }
  }

  // Set the configuration directory
  String configPath = configDir + File.separator + CONFIG_FILE_NAME;
  File configFile = new File(configPath);
  if (!configFile.exists()) {
    try {
      configFile.createNewFile();
    } catch (IOException e) {
      System.err.println("Error creating configuration file");
      System.err.println(e.getMessage());
      System.exit(1);
    }
  }
}

