public void writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    int length = str.length();
    for (int i = 0; i < length; i++) {
        final char c = str.charAt(i);
        if (c < 0x80) {
            lb.write(c);
        } else if (c < 0x800) {
            lb.write(0xC0 | (c >> 6));
            lb.write(0x80 | (c & 0x3F));
        } else if (Character.isHighSurrogate(c)) {
            final char c2 = str.charAt(++i);
            if (Character.isLowSurrogate(c2)) {
                final int codePoint = Character.toCodePoint(c, c2);
                lb.write(0xF0 | (codePoint >> 18));
                lb.write(0x80 | ((codePoint >> 12) & 0x3F));
                lb.write(0x80 | ((codePoint >> 6) & 0x3F));
                lb.write(0x80 | (codePoint & 0x3F));
            } else {
                // handle error - character c is a high surrogate but c2 is not a low surrogate
            }
        } else {
            lb.write(0xE0 | (c >> 12));
            lb.write(0x80 | ((c >> 6) & 0x3F));
            lb.write(0x80 | (c & 0x3F));
        }
    }
}

